package com.fincore.fincore.transaction; import java.time.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.fincore.fincore.account.*; import com.fincore.fincore.budget.BudgetRepository; import com.fincore.fincore.exception.*; @Service public class TransactionService {private final TransactionRepository txs;private final AccountRepository accounts;private final BudgetRepository budgets;public TransactionService(TransactionRepository t,AccountRepository a,BudgetRepository b){txs=t;accounts=a;budgets=b;}@Transactional public TransactionResponse create(Long uid,CreateTransactionRequest r){Account a=accounts.findByIdForUpdate(r.accountId()).orElseThrow(()->new NotFoundException("Account not found"));if(!a.getUser().getId().equals(uid))throw new ForbiddenException("You do not own this account");if(r.type()==TransactionType.EXPENSE&&a.getBalance().compareTo(r.amount())<0)throw new BadRequestException("Insufficient funds");Instant when=r.occurredAt()==null?Instant.now():r.occurredAt();if(r.type()==TransactionType.EXPENSE){YearMonth ym=YearMonth.from(when.atZone(ZoneOffset.UTC));budgets.findByUserIdAndCategoryIgnoreCaseAndMonth(uid,r.category(),ym.atDay(1)).ifPresent(b->{var start=ym.atDay(1).atStartOfDay(ZoneOffset.UTC).toInstant();var end=ym.plusMonths(1).atDay(1).atStartOfDay(ZoneOffset.UTC).toInstant();var spent=txs.spent(uid,r.category(),start,end);if(spent.add(r.amount()).compareTo(b.getAmount())>0)throw new BadRequestException("This expense exceeds the monthly budget for "+r.category());});a.setBalance(a.getBalance().subtract(r.amount()));}else a.setBalance(a.getBalance().add(r.amount()));var t=txs.save(new FinanceTransaction(r.amount(),r.category().trim(),r.description(),r.type(),a,a.getUser(),when));return TransactionResponse.from(t);}@Transactional(readOnly=true) public Page<TransactionResponse> all(Long uid,Pageable p){return txs.findAllByUserId(uid,p).map(TransactionResponse::from);}@Transactional(readOnly=true) public TransactionResponse one(Long uid,Long id){return TransactionResponse.from(txs.findByIdAndUserId(id,uid).orElseThrow(()->new NotFoundException("Transaction not found")));}}
